const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const geo = items[i].json;
  const orig = $('Merge').all()[i].json;

  if (geo.status === 'OK' && geo.results[0]) {
    const loc = geo.results[0].geometry.location;
    results.push({
      json: {
        ...orig,
        lat: loc.lat,
        lng: loc.lng
      }
    });
  }
}

return results;

const all = $input.first().json.data;
const kandidat = all.find(x => x.type === 'kandidat');
const shops = all.filter(x => x.type === 'shop');

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const nearby = [];

for (const s of shops) {
  const d = distance(kandidat.lat, kandidat.lng, s.lat, s.lng);
  const dist = Math.round(d*10)/10;
  if (d <= kandidat.max_distanz_km) {
    nearby.push({ id: s.id, name: s.name, dist });
  }
}

nearby.sort((a,b) => a.dist - b.dist);

const text = nearby.map((x,i) => `${i+1}. ${x.name}: ${x.dist} km`).join('\n');

return [{
  json: {
    kandidat_name: kandidat.name,
    kandidat_id: kandidat.id,
    anzahl: nearby.length,
    shops: nearby.map(x => x.name),
    distanzen: nearby.map(x => x.dist),
    shop_ids: nearby.map(x => x.id),
    min_dist: nearby[0]?.dist || 0,
    comment: nearby.length > 0 ? 'Zugeordnete Geschäfte:\n' + text : 'Keine Geschäfte gefunden'
  }
}];
